<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api'
import { duration, errorText, formatDate, percent, statusLabel } from '../utils'
import type { AiCall, AiStats, Page, TicketStats } from '../types'
const route = useRoute(), ai = computed(() => route.path.endsWith('/ai'))
const loading = ref(false), error = ref(''), dates = ref<[string,string]|null>(null), capability = ref(''), result = ref(''), page = ref(1), total = ref(0)
const tickets = ref<TicketStats|null>(null), stats = ref<AiStats|null>(null), calls = ref<AiCall[]>([])
const capabilities = ['KNOWLEDGE_CHAT','AGENT','TICKET_SUGGESTIONS','TICKET_SUMMARY','TICKET_DRAFT','SIMILAR_SEARCH','INDEX']
async function load() {
  loading.value = true; error.value = ''
  const filters = { startAt: dates.value?.[0], endAt: dates.value?.[1], capability: capability.value || undefined }
  try { if (ai.value) { const [summary, details] = await Promise.all([api<AiStats>('GET','/api/stats/ai',undefined,filters),api<Page<AiCall>>('GET','/api/ai/calls',undefined,{...filters,result:result.value || undefined,page:page.value,pageSize:10})]); stats.value = summary; calls.value = details.records; total.value = details.total } else tickets.value = await api('GET','/api/stats/tickets',undefined,filters) } catch(e) { error.value = errorText(e) } finally { loading.value = false }
}
function search() { page.value=1; void load() }
watch(ai,()=>{page.value=1;capability.value='';result.value='';void load()},{immediate:true})
</script><template><div class="page"><div class="page-header"><div><h1>{{ ai?'AI 使用统计':'工单统计' }}</h1><p class="subtitle">{{ ai?'查看能力使用、回答反馈与调用明细。':'了解当前权限范围内的服务请求与处理情况。' }}</p></div><el-button @click="load">刷新数据</el-button></div><section class="surface" v-loading="loading"><div class="toolbar"><el-date-picker v-model="dates" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ssZ" start-placeholder="开始时间" end-placeholder="结束时间" @change="search"/><el-select v-if="ai" v-model="capability" clearable placeholder="全部能力" @change="search"><el-option v-for="c in capabilities" :key="c" :label="statusLabel(c)" :value="c"/></el-select></div><el-alert v-if="error" :title="error" type="error" :closable="false"><template #default><el-button text @click="load">重新加载</el-button></template></el-alert><template v-if="!ai && tickets"><div class="summary-line"><div><span>工单总量</span><strong>{{ tickets.total }}</strong></div><div><span>平均处理时长</span><strong>{{ duration(tickets.averageResolutionSeconds) }}</strong></div></div><div class="stats-tables"><section><h2>状态分布</h2><el-table :data="tickets.statusDistribution"><el-table-column label="工单状态"><template #default="{row}"><span class="status" :class="row.status">{{ statusLabel(row.status) }}</span></template></el-table-column><el-table-column label="数量" prop="count" align="right"/></el-table></section><section><h2>分类分布</h2><el-table :data="tickets.categoryDistribution" empty-text="暂无分类数据"><el-table-column label="问题分类" prop="categoryName"/><el-table-column label="数量" prop="count" align="right"/></el-table></section></div><p class="form-help">平均处理时长：当前已解决或已关闭工单，从创建到最近一次标记已解决的平均时长。重新打开且尚未解决的工单不计入。</p></template><template v-else-if="ai && stats"><div class="summary-line"><div><span>调用次数</span><strong>{{ stats.callCount }}</strong></div><div><span>成功率</span><strong>{{ percent(stats.successRate) }}</strong></div><div><span>平均耗时</span><strong>{{ stats.averageDurationMs == null ? '未知' : `${(stats.averageDurationMs/1000).toFixed(2)} 秒` }}</strong></div></div><div class="stats-tables"><section><h2>用量与缓存</h2><dl class="metric-list"><dt>已知输入 token</dt><dd>{{ stats.knownInputTokens ?? '未知' }}</dd><dt>已知输出 token</dt><dd>{{ stats.knownOutputTokens ?? '未知' }}</dd><dt>用量不完整的调用</dt><dd>{{ stats.unknownUsageCallCount }}</dd><dt>缓存命中 / 可缓存请求</dt><dd>{{ stats.cacheHits }} / {{ stats.cacheEligibleRequests }}</dd><dt>缓存命中率</dt><dd>{{ percent(stats.cacheHitRate) }}</dd></dl></section><section><h2>回答反馈</h2><dl class="metric-list"><dt>自助解决率</dt><dd>{{ percent(stats.selfServiceResolutionRate) }}</dd><dt>反馈覆盖率</dt><dd>{{ percent(stats.feedbackCoverageRate) }}</dd><dt>收到反馈 / 回答数</dt><dd>{{ stats.feedbackCount }} / {{ stats.answerCount }}</dd><dt>明确已解决</dt><dd>{{ stats.resolvedFeedbackCount }}</dd><dt>明确未解决</dt><dd>{{ stats.unresolvedFeedbackCount }}</dd></dl></section></div><p class="form-help">未返回的用量标记为未知。自助解决率仅按明确反馈计算，无反馈不代表问题已解决；当前不计算费用。</p><hr class="section-rule"><div class="page-header"><h2>调用明细</h2><el-select v-model="result" clearable placeholder="全部结果" style="width:140px" @change="search"><el-option label="成功" value="SUCCESS"/><el-option label="失败" value="FAILED"/></el-select></div><el-table :data="calls" empty-text="所选范围内暂无调用记录"><el-table-column label="时间" width="135"><template #default="{row}">{{ formatDate(row.createdAt) }}</template></el-table-column><el-table-column label="能力" min-width="120"><template #default="{row}">{{ statusLabel(row.capability) }}</template></el-table-column><el-table-column label="模型" prop="model" min-width="130"/><el-table-column label="耗时" width="100"><template #default="{row}">{{ (row.durationMs/1000).toFixed(2) }} 秒</template></el-table-column><el-table-column label="输入 / 输出 token" min-width="150"><template #default="{row}">{{ row.inputTokens ?? '未知' }} / {{ row.outputTokens ?? '未知' }}</template></el-table-column><el-table-column label="结果" width="90"><template #default="{row}"><span class="status" :class="row.result">{{ statusLabel(row.result) }}</span></template></el-table-column><el-table-column label="关联 / 错误" min-width="180"><template #default="{row}"><RouterLink v-if="row.ticketId" :to="`/tickets/${row.ticketId}`">查看工单</RouterLink><span v-else>{{ row.errorSummary || '—' }}</span></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/></template><el-empty v-else-if="!loading && !error" description="暂无统计数据"/></section></div></template><style scoped>.summary-line{display:flex;gap:55px;padding:18px 0 32px;border-bottom:1px solid #edf0f4;margin-bottom:30px;flex-wrap:wrap}.summary-line span{display:block;color:#8191a1;font-size:12px;margin-bottom:14px}.summary-line strong{font-size:30px;font-weight:550;letter-spacing:-.5px}.stats-tables{display:grid;grid-template-columns:1fr 1fr;gap:36px;margin-bottom:24px}.metric-list{display:grid;grid-template-columns:1fr auto;gap:18px;font-size:13px}.metric-list dt{color:#758698}.metric-list dd{margin:0;font-variant-numeric:tabular-nums}@media(max-width:700px){.stats-tables{grid-template-columns:1fr}.summary-line{gap:30px}.summary-line strong{font-size:25px}}</style>
